HOOKS = {'before_tool': [], 'after_response': []}

def register(event, fn, mandatory=False):
    HOOKS[event].append({'fn': fn, 'mandatory': mandatory})

def run_hooks(event, payload):
    for hook in HOOKS.get(event, []):
        try: payload = hook['fn'](payload)
        except Exception:
            if hook['mandatory']: raise
    return payload
